SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `appointments`;
CREATE TABLE `appointments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `patient_id` int NOT NULL,
  `encounter_id` int DEFAULT NULL,
  `created_by_doctor` int NOT NULL,
  `appt_datetime` datetime NOT NULL,
  `appt_type` enum('followup','cga','other') DEFAULT 'followup',
  `status` enum('scheduled','completed','cancelled','no_show') DEFAULT 'scheduled',
  `note` text,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `encounter_id` (`encounter_id`),
  KEY `idx_appt_patient_time` (`patient_id`,`appt_datetime`),
  KEY `idx_appt_doctor_time` (`created_by_doctor`,`appt_datetime`),
  CONSTRAINT `appointments_ibfk_1` FOREIGN KEY (`patient_id`) REFERENCES `patients` (`id`),
  CONSTRAINT `appointments_ibfk_2` FOREIGN KEY (`encounter_id`) REFERENCES `encounters` (`id`),
  CONSTRAINT `appointments_ibfk_3` FOREIGN KEY (`created_by_doctor`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `assessment_answers`;
CREATE TABLE `assessment_answers` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `session_id` int NOT NULL,
  `cga_id` int DEFAULT NULL,
  `instrument` varchar(50) NOT NULL,
  `question_no` int NOT NULL,
  `answer_int` int DEFAULT NULL,
  `answer_text` text,
  `score` int DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_answers_cga` (`cga_id`),
  KEY `idx_answers_session` (`session_id`),
  KEY `idx_answers_instrument` (`instrument`),
  KEY `idx_answers_session_instrument` (`session_id`,`instrument`),
  CONSTRAINT `fk_answers_cga` FOREIGN KEY (`cga_id`) REFERENCES `cga_headers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_answers_session` FOREIGN KEY (`session_id`) REFERENCES `assessment_sessions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7055 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

