DROP TABLE IF EXISTS `assessment_revisions`;
CREATE TABLE `assessment_revisions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `session_id` int NOT NULL,
  `cga_id` int DEFAULT NULL,
  `instrument` varchar(50) DEFAULT NULL,
  `revision_no` int NOT NULL DEFAULT '1',
  `change_type` enum('create','update','delete') NOT NULL DEFAULT 'update',
  `changed_by` int DEFAULT NULL,
  `changed_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `snapshot_json` json DEFAULT NULL,
  `note` text,
  PRIMARY KEY (`id`),
  KEY `fk_rev_cga` (`cga_id`),
  KEY `idx_rev_session` (`session_id`),
  KEY `idx_rev_instrument` (`instrument`),
  KEY `idx_rev_changed_at` (`changed_at`),
  CONSTRAINT `fk_rev_cga` FOREIGN KEY (`cga_id`) REFERENCES `cga_headers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_rev_session` FOREIGN KEY (`session_id`) REFERENCES `assessment_sessions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `assessment_scores`;
CREATE TABLE `assessment_scores` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `session_id` int NOT NULL,
  `cga_id` int DEFAULT NULL,
  `instrument` varchar(50) NOT NULL,
  `total_score` int DEFAULT '0',
  `risk_level` varchar(30) DEFAULT NULL,
  `note` text,
  `computed_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_scores_session_instrument` (`session_id`,`instrument`),
  KEY `fk_scores_cga` (`cga_id`),
  KEY `idx_scores_session` (`session_id`),
  KEY `idx_scores_instrument` (`instrument`),
  KEY `idx_scores_risk` (`risk_level`),
  CONSTRAINT `fk_scores_cga` FOREIGN KEY (`cga_id`) REFERENCES `cga_headers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_scores_session` FOREIGN KEY (`session_id`) REFERENCES `assessment_sessions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `assessment_sessions`;
CREATE TABLE `assessment_sessions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `encounter_id` int NOT NULL,
  `session_type` enum('baseline','3m','6m','12m','adhoc') NOT NULL DEFAULT 'baseline',
  `assessed_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` enum('draft','completed','void') NOT NULL DEFAULT 'completed',
  `created_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_sessions_encounter` (`encounter_id`),
  KEY `idx_sessions_assessed_at` (`assessed_at`),
  CONSTRAINT `fk_session_encounter` FOREIGN KEY (`encounter_id`) REFERENCES `encounters` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=195 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

