DROP TABLE IF EXISTS `assessment_versions`;
CREATE TABLE `assessment_versions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `assessment_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `version` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `effective_date` date DEFAULT NULL,
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_assess_versions` (`assessment_type`,`version`),
  KEY `idx_assess_active` (`assessment_type`,`is_active`),
  KEY `fk_assess_versions_created_by` (`created_by`),
  CONSTRAINT `fk_assess_versions_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `assessment_versions` (`id`, `assessment_type`, `version`, `effective_date`, `description`, `is_active`, `created_by`, `created_at`) VALUES
