DROP TABLE IF EXISTS `cga_headers`;
CREATE TABLE `cga_headers` (
  `id` int NOT NULL AUTO_INCREMENT,
  `encounter_id` int NOT NULL,
  `session_id` int DEFAULT NULL,
  `assessed_by` int DEFAULT NULL,
  `assessed_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `overall_risk` enum('low','medium','high') DEFAULT NULL,
  `note` text,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `status` varchar(50) DEFAULT 'in_progress',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cga_per_encounter` (`encounter_id`),
  KEY `assessed_by` (`assessed_by`),
  KEY `idx_cga_headers_session` (`session_id`),
  CONSTRAINT `cga_headers_ibfk_1` FOREIGN KEY (`encounter_id`) REFERENCES `encounters` (`id`),
  CONSTRAINT `cga_headers_ibfk_2` FOREIGN KEY (`assessed_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_cga_headers_session` FOREIGN KEY (`session_id`) REFERENCES `assessment_sessions` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=185 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

