DROP TABLE IF EXISTS `cga_records`;
CREATE TABLE `cga_records` (
  `id` int NOT NULL AUTO_INCREMENT,
  `encounter_id` int DEFAULT NULL,
  `patient_id` int DEFAULT NULL,
  `hn` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `full_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `assessed_date` date DEFAULT NULL,
  `age` int DEFAULT NULL,
  `education` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `caregiver_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `caregiver_relation` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `emergency_phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `smoke` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `alcohol` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mmse_score` int DEFAULT NULL,
  `mmse_result` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tgds_score` int DEFAULT NULL,
  `tgds_result` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `suicide_risk` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `incontinence` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sleep_problem` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vision_left` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vision_right` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hearing_left` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hearing_right` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `q8_score` int DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `gender` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `birth_date` date DEFAULT NULL,
  `alcohol_amount` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=183 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

