DROP TABLE IF EXISTS `doctor_duties`;
CREATE TABLE `doctor_duties` (
  `id` int NOT NULL AUTO_INCREMENT,
  `doctor_id` int NOT NULL,
  `duty_date` date NOT NULL,
  `shift_type` enum('day','evening','night','oncall') NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `location` varchar(120) DEFAULT NULL,
  `note` text,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_doctor_shift` (`doctor_id`,`duty_date`,`shift_type`),
  KEY `idx_duty_doctor_date` (`doctor_id`,`duty_date`),
  CONSTRAINT `doctor_duties_ibfk_1` FOREIGN KEY (`doctor_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `doctor_notes`;
CREATE TABLE `doctor_notes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `encounter_id` int NOT NULL,
  `doctor_id` int NOT NULL,
  `diagnosis` text,
  `plan` text,
  `followup_note` text,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_notes_encounter` (`encounter_id`),
  KEY `idx_notes_doctor` (`doctor_id`,`created_at`),
  CONSTRAINT `doctor_notes_ibfk_1` FOREIGN KEY (`encounter_id`) REFERENCES `encounters` (`id`),
  CONSTRAINT `doctor_notes_ibfk_2` FOREIGN KEY (`doctor_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `encounters`;
CREATE TABLE `encounters` (
  `id` int NOT NULL AUTO_INCREMENT,
  `patient_id` int NOT NULL,
  `encounter_date` date NOT NULL,
  `encounter_type` enum('cga','followup','other') DEFAULT 'cga',
  `created_by` int DEFAULT NULL,
  `note` text,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `assigned_doctor_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `patient_id` (`patient_id`),
  KEY `created_by` (`created_by`),
  KEY `idx_encounters_doctor` (`assigned_doctor_id`),
  CONSTRAINT `encounters_ibfk_1` FOREIGN KEY (`patient_id`) REFERENCES `patients` (`id`),
  CONSTRAINT `encounters_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_encounters_doctor` FOREIGN KEY (`assigned_doctor_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=204 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

